body:
{
  "pains": [
    {
      "id": "pain:tax-filed-wrong",
      "statement": "I only find out my payroll taxes were filed wrong when the state sends me the bill.",
      "element": "b2b:ease_of_doing_business:risk_reduction",
      "shape": {
        "surface": "A notice lands from a state revenue, labor or UI agency about a filing the payroll provider was supposed to have handled.",
        "operational": "The owner or their CPA reconstructs a quarter of filings by hand, calls the agency, pays the penalty to stop the clock, then spends weeks trying to get reimbursed by the provider.",
        "personal": "They stop believing anything is actually being filed and start re-checking every quarter themselves, which is precisely the work they paid to stop doing."
      },
      "workflow": "Quarterly, in the window between the 941 and state UI deadline and the agency notice arriving: the owner has the provider's tax tab open in one window and the state portal in the other, cross-checking amounts line by line.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "A state agency notice or penalty assessment arrives in the mail", "cites": ["src:31", "src:32", "src:38"] },
        { "event": "The provider emails a warning that filing data (risk class codes, registration numbers) is wrong", "cites": ["src:2"] },
        { "event": "The account gets suspended over an alleged tax issue right before a payroll run", "cites": ["src:6"] },
        { "event": "Year-end W-2s come back with wrong numbers on them", "cites": ["src:27"] }
      ],
      "who_feels": ["economic_buyer", "technical_evaluator"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "I have almost no confidence that Gusto is filing the taxes properly because I get emails warning of errors, for example, that our L&I risk class codes are incorrect and they may not be able to file properly as a result. Except when I check our information, it is all correct and updated.",
              "cites": ["src:2"]
            },
            {
              "situation": "venting",
              "verbatim": "They withheld $$'s from our bank but didn't file the State quarterly until 5 months later, resulting in thousands of $'s in penalties to us.",
              "cites": ["src:31"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "The upshot is I have been having to file L&I taxes myself, which kind of makes me pissed about paying every month for gusto to NOT do their job.",
              "cites": ["src:2"]
            }
          ],
          "costs_them": "The penalty itself plus days of unbilled owner time reconciling filings, and in the worst case a suspended account two hours before payroll for 76 people.",
          "fears": "That the errors are compounding quietly and the real bill shows up at year-end, or that the IRS treats it as their failure, not the provider's.",
          "dream_outcome": "Never hear from a tax agency again, because the filings are right and the provider proves it before the agency does."
        },
        "technical_evaluator": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "After this situation I had my accountant look closer and she pointed out that Gusto was incorrectly filing state taxes.",
              "cites": ["src:38"]
            },
            {
              "situation": "when_comparing",
              "verbatim": "It took over $1000 in CPA fees before Gusto admitted this costly error... pay the extra fee now with ADP or Paychex or pay later...in the thousands.",
              "cites": ["src:36"]
            },
            {
              "situation": "venting",
              "verbatim": "their Philippines-based support team gave me incorrect information that could have gotten me in BIG trouble with the IRS if my accountant hadn't fixed it.",
              "cites": ["src:41"]
            }
          ],
          "costs_them": "Billable hours spent cleaning up a provider's filing errors that the client resents paying for, and a referral relationship they have to defend.",
          "fears": "That they recommended the platform and now own the mistake in the client's eyes.",
          "dream_outcome": "Filings they can spot-check in two minutes and sign off on without touching a state portal."
        }
      },
      "segments": ["seg:micro", "seg:smb", "seg:accountants"],
      "feature_ref": "feat:payroll",
      "cites": ["src:2", "src:6", "src:27", "src:30", "src:31", "src:32", "src:36", "src:38", "src:39", "src:41", "src:51"]
    },
    {
      "id": "pain:new-state-registration",
      "statement": "Every time someone moves or I hire out of state, I'm registering with three new agencies before I can legally pay them.",
      "element": "b2b:table_stakes:regulatory_compliance",
      "shape": {
        "surface": "A hire or a relocation means new state income tax withholding, a new unemployment insurance account and new workers' comp, each with its own portal and its own wait.",
        "operational": "The owner fills in state registration forms, waits on account numbers, guesses at rates in the meantime, and then chases wage transfers between states that can drag for months.",
        "personal": "A growth decision they were excited about turns into weeks of paperwork they resent, and they start quietly preferring contractors over employees."
      },
      "workflow": "At the offer-accepted moment, before the first payroll can run: the owner is bouncing between the payroll provider's 'add a state' flow, the state's Secretary of State site, the state UI portal and a workers' comp broker.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Hiring the first employee in a state the business has never operated in", "cites": ["src:43", "src:45"] },
        { "event": "An existing employee moves to another state", "cites": ["src:30"] },
        { "event": "Employees cross the day-count threshold that forces registration", "cites": ["src:44", "src:53"] }
      ],
      "who_feels": ["economic_buyer", "champion"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "I want to hire employees (not contractors) all over the United States but it is such a pain.",
              "cites": ["src:43"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "I did that in 2 states already (in addition to primary state) and drowning with shitty paperwork.",
              "cites": ["src:44"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "I had two employees move from Utah to Massachusetts in September 2025. The transition between states was not managed properly by Gusto, and I ended up in a SEVEN MONTH LONG battle with the state to transfer their wages.",
              "cites": ["src:30"]
            },
            {
              "situation": "venting",
              "verbatim": "I want a federal law in the United States that allows you to hire anyone in any state without doing the 'Register in my state' bullshit.",
              "cites": ["src:47"]
            }
          ],
          "costs_them": "Weeks of calendar delay per state, direct registration and broker costs, and in one documented case a $1,000 payment just to make the state stop asking.",
          "fears": "That they are already out of compliance in a state they didn't realize they had triggered, and won't know until it's a penalty.",
          "dream_outcome": "Type the new address, and every state account, rate and filing is opened and maintained without them touching a portal."
        },
        "champion": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "We use Gusto for payroll but have to spend a not-insignificant amount of time wrestling with each state's system.",
              "cites": ["src:46"]
            },
            {
              "situation": "when_looking",
              "verbatim": "When you hire an employee in a new state, you usually have to do these things differently: 1. State income and payroll taxes 2. State unemployment insurance 3. Workers compensation insurance",
              "cites": ["src:45"]
            }
          ],
          "costs_them": "The person who runs ops absorbs multi-day registration chores on top of their actual job, with no way to hand it off.",
          "fears": "Being the one who missed a registration and made the company late paying a new hire.",
          "dream_outcome": "State setup is the provider's job, not a checklist they maintain in a spreadsheet."
        }
      },
      "segments": ["seg:micro", "seg:smb"],
      "feature_ref": "feat:compliance",
      "cites": ["src:30", "src:43", "src:44", "src:45", "src:46", "src:47", "src:53"]
    },
    {
      "id": "pain:payday-not-there",
      "statement": "It's payday, the money isn't in my account, and nobody can tell me where it is.",
      "element": "b2c:emotional:reduces_anxiety",
      "shape": {
        "surface": "Payroll shows submitted and confirmed, but the deposit hasn't landed by the time rent, a card payment or a grocery run is due.",
        "operational": "The employee opens a chat, gets told there's no guaranteed deposit time, and waits; the owner ends up writing manual checks, couriering them across states and lending staff money.",
        "personal": "For the employee it's a day of real financial fear over money they already earned; for the owner it's the humiliation of their team finding out before they do."
      },
      "workflow": "Payday morning, 6am to 5pm: employee refreshing their banking app, then the payroll app's paystub screen, then a support chat window; owner refreshing the payroll run status and calling support.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "Payday arrives and the deposit hasn't posted by the usual time", "cites": ["src:4", "src:28"] },
        { "event": "A payroll run bounces or is reversed and the record disappears", "cites": ["src:14", "src:25"] },
        { "event": "Account suspension hits hours before a scheduled run", "cites": ["src:6"] }
      ],
      "who_feels": ["end_user", "economic_buyer"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "As an employee I have to say Gusto is the worst payroll service ever. Payday is today. In every single job I've had since direct deposit was born, you wake up and your money is in your account. With gusto, it can be hours or all day...",
              "cites": ["src:28"]
            },
            {
              "situation": "venting",
              "verbatim": "My paycheck is late and they say there is nothing wrong, but it will be deposited by 7 PM CT. Seriously?! Chatted with a rep who had a nonchalant attitude and said we never guarantee the checks will be deposited first thing in the morning.",
              "cites": ["src:4"]
            },
            {
              "situation": "venting",
              "verbatim": "BEEN WAITING ON A PAYMENT FOR 10+ DAYS, IT SAYS CONFIRMED BUT ITS NOT IN MY ACCOUNT",
              "cites": ["src:22"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "They dont help employees. If an employer doesnt pay and payroll bounces they dont leave it to show it. Instead delete it and say 'We cant see it since it wasnt run'. Even though it was ran it just bounced",
              "cites": ["src:14"]
            }
          ],
          "costs_them": "Overdraft fees, late rent, and a workday lost to chat queues over money they've already earned.",
          "fears": "That the employer or the platform has lost their pay and there is no record they can point to.",
          "dream_outcome": "The money is there when they wake up, every single time, with no thought required."
        },
        "economic_buyer": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "Payroll was submitted days ago. Its 2:30 pm on payday, still no deposits. They may even hold the money until Monday. How do they get away with being this terrible?",
              "cites": ["src:5"]
            },
            {
              "situation": "venting",
              "verbatim": "Every single pay period I spend half a day with AI chatbots, horrible UX, and roundabout solves just to pay one employee.",
              "cites": ["src:12"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "I had to figure out paychecks for 76 people, write out checks, fedex checks to 3 states and make loans to staff who could not get checks in bank. I never would have believed this could happen.",
              "cites": ["src:6"]
            }
          ],
          "costs_them": "Emergency manual payroll, courier costs, personal loans to staff, and standing in front of the team explaining a failure that isn't theirs.",
          "fears": "Losing the trust of people whose livelihoods they are responsible for, and the legal exposure of late wages.",
          "dream_outcome": "Payday is a non-event they never hear about."
        }
      },
      "segments": ["seg:micro", "seg:smb"],
      "feature_ref": "feat:payroll",
      "cites": ["src:4", "src:5", "src:6", "src:12", "src:14", "src:22", "src:25", "src:28", "src:59"]
    },
    {
      "id": "pain:no-one-to-call",
      "statement": "When payroll breaks I get a chatbot and a rep with no authority, and payroll cannot wait three weeks.",
      "element": "b2b:ease_of_doing_business:responsiveness",
      "shape": {
        "surface": "Support is reachable but useless: message-passing reps, AI chat, no supervisor available, weeks between replies.",
        "operational": "The customer compiles their own case timeline, re-explains it to each new agent, and often ends up paying an accountant or fixing the filing themselves.",
        "personal": "They feel deliberately walled off by a company holding their employees' pay, and the gap between the sales experience and the service experience reads as a bait and switch."
      },
      "workflow": "Mid-crisis, after a failed run or a tax notice: the buyer is in the in-app chat, then the phone tree, then email, keeping their own log because nobody on the other side has one.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "A payroll run fails or a deposit doesn't land and the clock is running", "cites": ["src:9", "src:13"] },
        { "event": "A tax or benefits error needs a human with authority to override", "cites": ["src:8", "src:10"] },
        { "event": "Something breaks outside weekday business hours", "cites": ["src:56"] }
      ],
      "who_feels": ["economic_buyer", "champion", "technical_evaluator"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Try getting someone knowledgeable on the phone. Good luck. And when you finally reach someone, communication can be extremely difficult, and instead of getting your problem solved, prepare yourself for more questions than an FBI profiler interrogating a suspected serial killer.",
              "cites": ["src:3"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "we cannot get a real response out of them...going on 3 weeks. I still have no answers.",
              "cites": ["src:20"]
            },
            {
              "situation": "when_comparing",
              "verbatim": "I left Paychex because I thought their service was terrible. Gusto somehow managed to make me appreciate Paychex. I didn't think that was possible.",
              "cites": ["src:3"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "It is clear that their customer support system is set up as a firewall to ensure actual employees never have to interact with dissatisfied clients. The support reps function strictly as a go-between, passing messages back and forth without any real authority to fix the company's bad service.",
              "cites": ["src:15"]
            }
          ],
          "costs_them": "Hours per incident, repeated across every pay cycle, plus the cost of hiring an accountant to do what support couldn't.",
          "fears": "That the next failure is the one nobody fixes in time, and the employees pay for it.",
          "dream_outcome": "One named person who knows their account and can actually change something, reachable the day payroll breaks."
        },
        "champion": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "Spoke with 5 customer service agents over the course of 1.5 hours and no one was able to help me understand my account balance (many numbers were incorrectly given). I asked to speak to a manager or supervisor and no one was available. Nothing was resolved in over 1.5 hours and I missed 2 other important meetings.",
              "cites": ["src:10"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "At one point I had to compile my own complete case timeline myself and send it to Gusto's own 'support staff', because nobody there had reviewed the case before responding to me.",
              "cites": ["src:8"]
            },
            {
              "situation": "when_comparing",
              "verbatim": "customer support is only during weekday hours. There is no weekend availability",
              "cites": ["src:56"]
            }
          ],
          "costs_them": "The office manager or ops lead becomes the case manager for their own vendor, losing whole days to it.",
          "fears": "Having recommended the tool and now being the one who can't get an answer for the boss.",
          "dream_outcome": "Escalation that actually escalates, with someone who has read the case before they pick up."
        },
        "technical_evaluator": {
          "says": [
            {
              "situation": "when_comparing",
              "verbatim": "The support is AI...chat with techs who know less about the software than most users.",
              "cites": ["src:26"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "Payroll problems are time-sensitive and affect employees directly, so slow or unclear support creates real operational stress for a business. We expected better communication, clearer escalation, and faster help.",
              "cites": ["src:13"]
            }
          ],
          "costs_them": "Time they can't bill, spent brokering between a client and a vendor that won't answer either of them.",
          "fears": "That support quality, not features, is what their whole client book will judge them on.",
          "dream_outcome": "A partner line where the first person they reach can see and fix the account."
        }
      },
      "segments": ["seg:micro", "seg:smb", "seg:accountants"],
      "feature_ref": null,
      "feature_note": "No feature in brain/company addresses this; it is a service-delivery pain. What would kill it is a named human with real authority per account and a stated response-time commitment during payroll-critical windows, which the company's own site does not name as a product.",
      "cites": ["src:3", "src:8", "src:10", "src:13", "src:15", "src:17", "src:20", "src:26", "src:56", "src:57", "src:60"]
    },
    {
      "id": "pain:multi-client-blast-radius",
      "statement": "One client's billing problem locked me out of every client's payroll.",
      "element": "b2b:functional:scalability",
      "shape": {
        "surface": "The accountant's single login is the access point for a whole book of client businesses, so any account-level action hits all of them at once.",
        "operational": "A lockout, a billing dispute or a support failure on one client stops payroll for every client that week; the firm has to migrate the whole book to prove it won't happen again.",
        "personal": "The accountant's reputation is tied to a platform they referred clients into, and a single failure makes them look careless to all of them at once."
      },
      "workflow": "Payroll week across a client book: the accountant is switching between client accounts in one console, approving runs, and reconciling each client's filings back into their own ledger software.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        { "event": "One client's bill goes unpaid or a promo lapses without notice", "cites": ["src:33", "src:34"] },
        { "event": "A run fails for one client and support won't escalate", "cites": ["src:9"] },
        { "event": "Mid-year cancellation leaves a client's W-2 processing undefined", "cites": ["src:35"] }
      ],
      "who_feels": ["technical_evaluator", "champion"],
      "by_role": {
        "technical_evaluator": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "I had my account locked out. I have hundreds of clients I work with and because a single one didn't pay their bill, I am locked out of ALL the accounts I'm linked to.",
              "cites": ["src:34"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "Accountants beware, this is NOT the company for you.",
              "cites": ["src:34"]
            },
            {
              "situation": "when_comparing",
              "verbatim": "I'm a CPA who runs payroll for client businesses on Gusto — every one of those clients came in through my referrals.",
              "cites": ["src:33"]
            }
          ],
          "costs_them": "Every client's payroll week at once, plus the migration cost of moving a book to another provider.",
          "fears": "That an account-level action they don't control can freeze their entire practice's service delivery.",
          "dream_outcome": "Client accounts that fail independently, and a firm-level relationship that isn't hostage to one client's invoice."
        },
        "champion": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "I have had three clients on the system and ran into a glitch with one. I dealt with customer service on two occasions and gave them a second chance when a payroll failed to direct deposit funds on time for our employees.",
              "cites": ["src:9"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "I have removed all of my clients from Gusto's platform and will not be returning. Trust is critical in payroll services.",
              "cites": ["src:35"]
            }
          ],
          "costs_them": "The bookkeeper who introduced the platform now owns the cleanup and the client conversations.",
          "fears": "Losing clients over a vendor choice they made.",
          "dream_outcome": "A book of clients they can run without ever explaining the software to anyone."
        }
      },
      "segments": ["seg:accountants"],
      "feature_ref": null,
      "feature_note": "brain/company lists no accountant-side product at all, only the single-business product. What would kill this is a firm-level console with per-client isolation, firm billing separate from client billing, and a partner support line.",
      "cites": ["src:9", "src:33", "src:34", "src:35"]
    },
    {
      "id": "pain:benefits-cost-and-maze",
      "statement": "Offering health insurance costs me more than another hire and the rules change on me every renewal.",
      "element": "b2b:ease_of_doing_business:simplification",
      "shape": {
        "surface": "Group premiums rise by double digits at renewal, and plan eligibility turns on where staff live and which carrier serves which county.",
        "operational": "The owner re-shops plans each year, reconciles deductions against carrier invoices, and fields employee questions about claims and cards they can't answer.",
        "personal": "They either eat a cost that dwarfs their own salary or lose candidates for not offering benefits, and they carry the guilt of a coverage lapse landing on someone's family."
      },
      "workflow": "At open enrollment and renewal: the owner is in the benefits tab comparing plan tiers, in a broker's spreadsheet, and in payroll checking that deduction amounts match what the carrier actually billed.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        { "event": "The annual renewal quote arrives with a double-digit increase", "cites": ["src:61"] },
        { "event": "Coverage lapses or is cancelled without the employer being told", "cites": ["src:24"] },
        { "event": "A candidate asks what benefits are offered", "cites": ["src:50"] },
        { "event": "An employee's claim or bill goes unpaid and they escalate to the employer", "cites": ["src:10"] }
      ],
      "who_feels": ["economic_buyer", "champion"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "I run a small business and it costs about $2000/Month group premium for a family of 4...So give or take, $25K per year per family/employee.",
              "cites": ["src:48"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "Gusto cancelled my employees' dental and vision insurance without telling me...Gusto is a danger to your business.",
              "cites": ["src:24"]
            },
            {
              "situation": "when_comparing",
              "verbatim": "health insurance companies make that massively complicated, with various rules about where the majority of staff lived, where each person lived, which plans were available",
              "cites": ["src:49"]
            },
            {
              "situation": "when_looking",
              "verbatim": "For the first year or so of our company, we didn't offer health benefits, and that cost us candidates...The current system distorts both the health care market and the job market",
              "cites": ["src:50"]
            }
          ],
          "costs_them": "Tens of thousands per covered family per year, plus weeks of renewal shopping and reconciliation that nobody bills for.",
          "fears": "Discovering coverage lapsed only when an employee's claim is denied.",
          "dream_outcome": "Benefits that renew, deduct and reconcile themselves, at a price they can forecast a year out."
        },
        "champion": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "My daughter pediatric bill has still not been paid. Considering moving our company benefits to someone else.",
              "cites": ["src:10"]
            },
            {
              "situation": "when_comparing",
              "verbatim": "The benefits management portion of Gusto dropped the ball in a pretty significant way.",
              "cites": ["src:58"]
            },
            {
              "situation": "venting",
              "verbatim": "Overpromised, repeated benefits errors, and painfully slow resolution",
              "cites": ["src:21"]
            }
          ],
          "costs_them": "They become the help desk for everyone's claims and cards without the access to resolve any of them.",
          "fears": "Being blamed by colleagues for a benefits failure they can only report, not fix.",
          "dream_outcome": "Deductions that always match the carrier invoice, and a single place to send an employee with a claim question."
        }
      },
      "segments": ["seg:micro", "seg:smb"],
      "feature_ref": "feat:benefits",
      "cites": ["src:10", "src:21", "src:24", "src:48", "src:49", "src:50", "src:58", "src:61"]
    },
    {
      "id": "pain:w2-hostage",
      "statement": "I left the job and now I can't get my W-2 out of a system I never signed up for.",
      "element": "b2c:functional:informs",
      "shape": {
        "surface": "Former employees lose access to pay records and year-end tax forms held in the employer's payroll platform.",
        "operational": "They chase the former employer, who chases a support queue, while a tax filing deadline runs down; if the employer cancelled mid-year, W-2 processing may not have been set up at all.",
        "personal": "Someone with no relationship to the vendor and no leverage is blocked from a document they legally need, at the one time of year it matters."
      },
      "workflow": "January to April: the ex-employee is logging into a payroll portal they no longer have access to, then emailing a former manager, then filing without the form.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        { "event": "Employment ends and portal access is cut", "cites": ["src:18"] },
        { "event": "The employer cancels the service mid-year and W-2 handling isn't defaulted on", "cites": ["src:35"] },
        { "event": "W-2 figures come back wrong and need correcting", "cites": ["src:27"] }
      ],
      "who_feels": ["end_user", "economic_buyer", "technical_evaluator"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Their customer service is awful and once you are no longing using them they hold your W2s",
              "cites": ["src:18"]
            }
          ],
